let planung = {};
try {
  const raw = $('Planungsdaten holen').item.json['Planungsdaten (JSON)'];
  planung = raw ? JSON.parse(raw) : {};
} catch (e) {
  planung = {};
}

const input = $('Input').item.json;
const meta = $('Metadaten-Agent').item.json.output;
const pickText = (n) => { try { const c = $(n).item.json.content; return Array.isArray(c) ? (c.find(x => x.type === 'text')?.text || '') : (c || ''); } catch (e) { return ''; } };
const coverPromptA = pickText('Cover_Promt');
const coverPromptB = pickText('Cover_Promt_2');

const heute = new Date().toISOString().slice(0, 16).replace('T', ' ');

const titelOptionen = (planung.titel_optionen || []).map((t, i) => `  ${i + 1}. ${t}`).join('\n') || '  (keine Daten - Buch vor Einfuehrung des Logs erstellt)';
const untertitelOptionen = (planung.untertitel_optionen || []).map((t, i) => `  ${i + 1}. ${t}`).join('\n') || '  (keine Daten)';
const kapitelListe = (planung.kapitel || []).map((k, i) => `  ${i + 1}. ${k.kapitel_titel_kurz} - ${k.beschreibung}`).join('\n') || '  (keine Daten)';

const text = `URHEBERSCHAFT-LOG
${input.titel}
Erstellt am: ${heute}


BLOCK 0 - SYSTEM-DOKUMENTATION
Uebergeordnete Architektur, eingesetzte Modelle und Prompt-Versionen dieser Buch-Pipeline sind zentral dokumentiert:
https://docs.google.com/document/d/GOOGLE_FILE_ID/edit


BLOCK 1 - KOPF- UND IDENTIFIKATIONSDATEN
Buch-ID: ${input.buch_id}
Titel: ${input.titel}
Untertitel: ${input.untertitel}
Pseudonym/Autor: ${input.autor}
Nische: ${input.nische}
Drive-Ordner: https://drive.google.com/drive/folders/${input.ordner_id}


BLOCK 2 - THEMEN-/NISCHENFINDUNG (menschliche Auswahlentscheidung)
Vorgeschlagene Titel:
${titelOptionen}
Gewaehlter Titel: ${planung.gewaehlter_titel || input.titel}

Vorgeschlagene Untertitel:
${untertitelOptionen}
Gewaehlter Untertitel: ${planung.gewaehlter_untertitel || input.untertitel}

Begruendung der Nischenwahl: ${planung.nische_begruendung || input.nische}
Freigegeben von: Herausgeber


BLOCK 3 - KONZEPTION / GLIEDERUNG
Kapitel (aus Struktur-Agent, vor Texterstellung freigegeben):
${kapitelListe}


BLOCK 4 - KI-TEXTERSTELLUNG
Modell: Claude Sonnet 5 (Schreib-Agent, Kontroll-Agent, Fix-Agent im Mehrfach-Pruef-Loop)
Sprache: Deutsch
Fertigstellung Manuskript: siehe Buch-Master-Sheet, Spalte "Fertig am"
Manuskript: im Drive-Ordner oben


BLOCK 5 - MENSCHLICHE REDAKTION & QUALITAETSKONTROLLE
STATUS: [AUSSTEHEND - Freigabe-Formular noch nicht abgeschickt]


BLOCK 6 - COVER- & BILDGENERIERUNG
Bildgenerierung: Recraft V4 Pro (via n8n)
Prompt-Erstellung: Claude Sonnet 5
Automatisierte Cover-Rechtschreibkontrolle: Claude Haiku 4.5
Verwendeter Prompt, Variante 1: ${coverPromptA}
Verwendeter Prompt, Variante 2: ${coverPromptB}
Beide Varianten liegen im Drive-Ordner. Gewaehlte Variante bitte hier nachtragen: [MANUELL]


BLOCK 7 - METADATEN-ERSTELLUNG
Erzeugt von: Metadaten-Agent (Claude Sonnet 5)
Buchbeschreibung, Keywords, Kategorien, Preisstrategie: siehe Buch-Master-Sheet
Geprueft von: Herausgeber [Datum nachtragen]


BLOCK 8 - KDP-COMPLIANCE / AI-DISCLOSURE
Disclosure Text: [MANUELL: Ja/Nein]
Disclosure Bilder: [MANUELL: Ja/Nein]
Datum der Angabe: [MANUELL]
ASIN (E-Book): [MANUELL]
ASIN (Taschenbuch): [MANUELL]


BLOCK 9 - MANUELLE ARBEITSSCHRITTE AUSSERHALB N8N
KDP-Upload (Datum): [MANUELL]
Print-Cover-Erstellung: [MANUELL]
Sonstiges: [MANUELL]


BLOCK 10 - VERANTWORTLICHE PERSON
Name: Herausgeber
Kontakt: you@example.com
Funktion: Herausgeber unter Pseudonym ${input.autor}


BLOCK 11 - VERSIONS-/AENDERUNGSHISTORIE
(nur bei spaeterer Bearbeitung relevant)


BLOCK 12 - AUFBEWAHRUNG
Dieses Dokument liegt dauerhaft im Buch-Ordner (siehe Block 1). Google Drive Versionshistorie dient als Manipulationsschutz.
`;

return { json: { log_text: text } };

// Fortsetzen ohne WF02: Wird WF03 nur mit einer Buch-ID gestartet (Testlauf-Starter),
// holt dieser Zweig die Buchdaten aus dem Buch-Master.
const b = $input.first().json || {};
let gesucht = '';
try { gesucht = String($('Start (von WF2)').first().json.buch_id || ''); } catch (e) {}
if (!b.Buchtitel) throw new Error('Buch-ID ' + gesucht + ' nicht im Buch-Master gefunden.');
return [{ json: {
  buch_id: String(b['Buch-ID']).trim(),
  titel: b.Buchtitel,
  untertitel: b.Untertitel,
  autor: b['Pseudonym (Autor)'],
  nische: b.Nische,
  ordner_id: b['Ordner-ID'],
  fortgesetzt: true
} }];
